from typing import Dict, List, Optional, Tuple

Mono = Dict[int, float]
Series = List[Tuple[Mono, float]]


def compare_mono(a: Mono, b: Mono) -> int:
    for h in sorted(set(a) | set(b), reverse=True):
        ea, eb = a.get(h, 0.0), b.get(h, 0.0)
        if ea < eb: return -1
        if ea > eb: return 1
    return 0


def series_sub(a: Series, b: Series) -> Series:
    acc: Dict[Tuple[Tuple[int, float], ...], float] = {}
    keep: Dict[Tuple[Tuple[int, float], ...], Mono] = {}
    for m, c in a:
        k = tuple(sorted(m.items())); acc[k] = acc.get(k, 0.0) + c; keep[k] = m
    for m, c in b:
        k = tuple(sorted(m.items())); acc[k] = acc.get(k, 0.0) - c; keep[k] = m
    return [(keep[k], v) for k, v in acc.items() if abs(v) > 1e-12]


def agree_to_all_orders(a: Series, b: Series) -> bool:
    """The asymptotic comparison theorem in action: a and b agree to all orders
    iff a - b has no surviving transmonomial, which (by agreeToAllOrders_iff_eq)
    happens iff a == b as transseries."""
    return series_sub(a, b) == []


if __name__ == "__main__":
    a: Series = [({1: 1.0}, 1.0), ({0: 1.0}, 3.0), ({}, -7.0)]      # e^x + 3x - 7
    reordered: Series = [({}, -7.0), ({0: 1.0}, 3.0), ({1: 1.0}, 1.0)]
    perturbed: Series = a + [({-1: 1.0}, 1e-9)]                      # + 1e-9 log x
    print("a agrees with a reordered :", agree_to_all_orders(a, reordered))  # True
    print("a agrees with a+1e-9 log x:", agree_to_all_orders(a, perturbed))  # False

